export function insertDeleteGetrandomO1(operations                     )                     {
const a         =[],positions=new Map               ();return operations.map(([op,arg])=>{const x=Number(arg);if(op==='getRandom')return a[x];if(op==='insert'){if(positions.has(x))return false;positions.set(x,a.length);a.push(x);return true;}const index=positions.get(x);if(index===undefined)return false;const last=a[a.length-1];a[index]=last;positions.set(last,index);a.pop();positions.delete(x);return true;});
}

